const hotels=[['29 OCT','Hotel Resol Trinity Osaka','Osaka · Agoda · Confirmed'],['30 OCT','Hotel Resol Trinity Kyoto','Kyoto · Agoda · Confirmed'],['02 NOV','Charoku Honkan','Miyazu · Agoda · Confirmed'],['03 NOV','Ryokan Onishiya Suishoen','Kinosaki Onsen · Agoda · Confirmed'],['04 NOV','Fairfield by Marriott Hyogo Awaji Higashiura','Awaji Island · Agoda · Confirmed'],['05 NOV','Hotel Resol Trinity Osaka','Osaka · Agoda · Confirmed']];let hotelMedia={},hotelPhotoLoading=new Set;try{let saved=JSON.parse(localStorage.getItem('tabi-trip-days'));if(Array.isArray(saved)&&saved.length)days.splice(0,days.length,...saved);hotelMedia=JSON.parse(localStorage.getItem('tabi-hotel-media'))||{}}catch{}days.forEach(d=>{if(!d.iso)d.iso=`2026-${Number(d.date)>=29?'10':'11'}-${String(d.date).padStart(2,'0')}`});function persistTrip(){try{localStorage.setItem('tabi-trip-days',JSON.stringify(days));localStorage.setItem('tabi-hotel-media',JSON.stringify(hotelMedia))}catch{}}let selected=2;
const typeClass=t=>t==='Meal'?'meal':t==='Transport'?'transport':'';
const placeChinese={
'Arrive at Kansai International Airport':'抵达关西国际机场','Into central Osaka':'前往大阪市中心','Check in & rest':'办理入住／休息','Dotonbori dinner':'道顿堀晚餐','Yodoyabashi to Kyoto':'淀屋桥前往京都','Leave luggage at hotel':'酒店寄存行李','Lunch near Kyoto Gosho':'京都御所附近午餐','Kyoto Imperial Palace':'京都御所','Kamogawa Delta':'鸭川三角洲','Dinner in Pontocho':'先斗町晚餐','Leave for Kiyomizu-dera':'前往清水寺','Kiyomizu-dera':'清水寺','Sannenzaka & Ninenzaka':'三年坂与二年坂','Matcha stop':'抹茶休息站','Kodaiji & Nene-no-Michi':'高台寺与宁宁之道','Gion Shirakawa':'祇园白川','Dinner near Pontocho':'先斗町附近晚餐','Train to Arashiyama':'前往岚山','Arashiyama Bamboo Grove':'岚山竹林','Jojakkoji & Gioji':'常寂光寺与祇王寺','Soba lunch':'荞麦面午餐','Togetsukyo Bridge':'渡月桥','Check out':'办理退房','Pick up rental car':'领取租车','Sanzen-in':'三千院','Lunch in Ohara':'大原午餐','Drive to Miyazu':'驾车前往宫津','Check in at Charoku Honkan':'入住茶六本馆','Amanohashidate View Land':'天桥立观景乐园','Chionji Temple':'智恩寺','Ine seafood lunch':'伊根海鲜午餐','Ine Funaya':'伊根舟屋','Drive to Kinosaki Onsen':'驾车前往城崎温泉','Ryokan dinner & onsen':'旅馆晚餐与温泉','Kinosaki town walk':'城崎温泉街散步','Kobe beef lunch':'神户牛午餐','Kobe harbour':'神户港','Across Akashi Kaikyo Bridge':'横跨明石海峡大桥','Check in on Awaji':'入住淡路岛','Higashiura coastal walk':'东浦海岸散步','Awaji Yumebutai':'淡路梦舞台','Drive to Osaka':'驾车前往大阪','Check in & collect luggage':'入住并取回行李','Dinner in Fukushima':'福岛区晚餐','Kuromon Market breakfast':'黑门市场早餐','Namba Yasaka Shrine':'难波八阪神社','Horie & Orange Street':'堀江与橘子街','Route A · Nakazakicho':'路线 A：中崎町','Route B · Osaka Castle':'路线 B：大阪城','Fukushima or Kitashinchi dinner':'福岛区或北新地晚餐','Breakfast nearby':'附近早餐','Final shopping':'最后购物','Return to hotel & collect luggage':'回酒店取行李','Depart for Kansai Airport':'前往关西机场','Flight to Melbourne':'飞往墨尔本'
};
Object.assign(placeChinese,{'Yasaka Shrine':'八坂神社','Fushimi Inari Taisha':'伏见稻荷大社','Kinkaku-ji':'金阁寺','Ginkaku-ji':'银阁寺','Nishiki Market':'锦市场','Osaka Castle':'大阪城','Dotonbori':'道顿堀','Umeda Sky Building':'梅田蓝天大厦','Shitenno-ji':'四天王寺','Tofuku-ji':'东福寺','Nijo Castle':'二条城','Philosopher\'s Path':'哲学之道'});
function chinesePlace(name){return placeChinese[name]||''}
function canonicalStopName(value){let typed=String(value||'').trim(),compact=typed.replace(/\s/g,'');for(let [english,chinese] of Object.entries(placeChinese))if(chinese.replace(/\s/g,'')===compact)return english;return typed}
function renderDays(){document.querySelector('#dashboard-days').innerHTML=days.map((d,i)=>`<button class="day-row" data-day="${i}"><span>${d.date}</span><div><b>${d.city}</b><small>${d.theme}</small></div><em>${d.dow}</em></button>`).join('');document.querySelectorAll('.day-row').forEach(b=>b.onclick=()=>{selected=+b.dataset.day;showPage('itinerary');renderItinerary()})}
const hotelChinese={'Hotel Resol Trinity Osaka':'大阪雷索尔三位一体酒店','Hotel Resol Trinity Kyoto':'京都雷索尔三位一体酒店','Charoku Honkan':'茶六本馆','Ryokan Onishiya Suishoen':'大西屋水翔苑旅馆','Fairfield by Marriott Hyogo Awaji Higashiura':'兵库淡路东浦万枫酒店'};
function renderHotels(){document.querySelector('#hotel-list').innerHTML=hotels.map((h,index)=>{let media=hotelMedia[h[1]]||{},booking=`https://www.agoda.com/search?text=${encodeURIComponent(h[1])}`;return `<article class="hotel-card"><div class="hotel-photo-slot">${media.photo?`<img src="${media.photo}" alt="${h[1]} visual reminder" onerror="this.parentElement.classList.add('missing-photo');this.remove()">`:''}<span class="hotel-photo-empty">⌂<small>Hotel photo</small></span></div><div class="hotel-copy"><span class="eyebrow">${h[0]}</span><b>${h[1]}</b><small class="card-translation">${hotelChinese[h[1]]||''}</small><small>${h[2]}</small></div><div class="hotel-actions"><a href="${media.website||booking}" target="_blank" rel="noreferrer">Booking ↗</a><button data-hotel-fill="${index}">${media.photo?'Refresh photo':'Auto-fill photo'}</button></div></article>`}).join('');document.querySelectorAll('[data-hotel-fill]').forEach(button=>button.onclick=()=>autoEnrichHotel(+button.dataset.hotelFill))}
async function autoEnrichHotel(index){let hotel=hotels[index],button=document.querySelector(`[data-hotel-fill="${index}"]`);if(!hotel||hotelPhotoLoading.has(hotel[1])||button?.disabled)return;hotelPhotoLoading.add(hotel[1]);if(button){button.disabled=true;button.textContent='Finding…'}try{let details=await wikidataPlaceDetails(`${hotel[1]} ${hotel[2].split('·')[0]}`);if(!details?.image){return}hotelMedia[hotel[1]]={...(hotelMedia[hotel[1]]||{}),photo:details.image,website:details.website||hotelMedia[hotel[1]]?.website};persistTrip();renderHotels();toast('Hotel photo added')}catch{}finally{hotelPhotoLoading.delete(hotel[1]);if(button?.isConnected){button.disabled=false;button.textContent='Auto-fill photo'}}}
function mapQuery(item,city){let extra=item[5]||{};return extra.place||(item[1]==='Stay'?item[3]:item[2])||city}
function countryForMapCity(city){let day=days.find(entry=>entry.city===city);return day?.country||inferredCountry(day||{city})||''}
function mapUrl(item,city){let country=countryForMapCity(city);return item[5]?.map||`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([mapQuery(item,city),city,country].filter(Boolean).join(', '))}`}
function canEnrich(item){let title=mapQuery(item,'');return item[1]!=='Transport'&&!/^(check in|check out|leave luggage|return to hotel|breakfast nearby|final shopping|lunch near|dinner near|dinner in|soba lunch|ine seafood lunch|kobe beef lunch|dotonbori dinner|fukushima or kitashinchi dinner|matcha stop|pick up rental car|across |drive to|depart for|arrive at|into central|train to|leave for|flight to)/i.test(title)}
function normalName(value){return String(value||'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}
async function wikidataPlaceDetails(name){let title=encodeURIComponent(name.trim().replace(/\s+/g,'_')),summary=null;for(let language of ['en','zh','ja']){summary=await fetch(`https://${language}.wikipedia.org/api/rest_v1/page/summary/${title}`).then(r=>r.ok?r.json():null).catch(()=>null);if(summary&&summary.type!=='disambiguation')break}if(!summary||summary.type==='disambiguation')return null;let website=summary.content_urls?.desktop?.page||'',image=summary.originalimage?.source||summary.thumbnail?.source||'',qid=summary.wikibase_item,englishName='';if(qid){try{let entityParams=new URLSearchParams({action:'wbgetentities',ids:qid,props:'labels|claims',languages:'en',format:'json',origin:'*'}),entityData=await fetch(`https://www.wikidata.org/w/api.php?${entityParams}`).then(r=>r.ok?r.json():null),entity=entityData?.entities?.[qid]||{},claims=entity.claims||{};englishName=entity.labels?.en?.value||'';website=claims.P856?.[0]?.mainsnak?.datavalue?.value||website;let commonsImage=claims.P18?.[0]?.mainsnak?.datavalue?.value;if(commonsImage)image=`https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(commonsImage)}?width=900`}catch{}}return {website,image,englishName}}
function autoEnrichNewItem(item,rawName,target){if(!item)return;wikidataPlaceDetails(item[2]).then(details=>{if(!details)return;let extra=item[5]||{},changed=false;if(details.englishName&&details.englishName!==item[2]){if(/[\u4e00-\u9fff]/.test(rawName))placeChinese[details.englishName]=rawName;item[2]=details.englishName;extra.place=details.englishName;changed=true}if(details.image&&!extra.photo){extra.photo=details.image;changed=true}if(details.website&&!extra.website){extra.website=details.website;changed=true}if(changed){item[5]=extra;persistTrip();if(selected===target)renderItinerary();toast('Place details added automatically')}}).catch(()=>{})}
async function enrichOneStop(index){let item=days[selected].items[index],button=document.querySelector(`[data-auto-enrich="${index}"]`);if(!item||button?.disabled)return;if(!canEnrich(item)){toast('This is a travel or flexible note, so it was left unchanged');return}if(button){button.disabled=true;button.textContent='Finding…'}try{let details=await wikidataPlaceDetails(mapQuery(item,days[selected].city)),extra=item[5]||{},changed=false;if(details?.website&&!extra.website){extra.website=details.website;changed=true}if(details?.image&&!extra.photo){extra.photo=details.image;changed=true}if(changed){item[5]=extra;persistTrip();renderItinerary();toast('Photo and website added where available')}else{toast('No confident public match — nothing changed')}}catch{toast('Could not reach place details — nothing changed')}finally{if(button?.isConnected){button.disabled=false;button.textContent='✦ Auto-fill'}}}
async function enrichAllPlaces(){let button=document.querySelector('#auto-enrich'),status=document.querySelector('#enrich-status');if(button.disabled)return;let candidates=[];days.forEach(d=>d.items.forEach(item=>{let extra=item[5]||{};if(canEnrich(item)&&(!extra.website||!extra.photo))candidates.push({item,city:d.city})}));if(!candidates.length){status.textContent='Everything that can be filled already has a photo and website.';return}button.disabled=true;button.textContent='Finding matches…';let completed=0,changed=0,cache=new Map();await Promise.all(candidates.map(async({item,city})=>{let name=mapQuery(item,city),key=normalName(name);try{let details=cache.get(key);if(!details){details=wikidataPlaceDetails(name);cache.set(key,details)}details=await details;let extra=item[5]||{},didChange=false;if(details?.website&&!extra.website){extra.website=details.website;didChange=true}if(details?.image&&!extra.photo){extra.photo=details.image;didChange=true}if(didChange){item[5]=extra;changed++}}catch{}finally{completed++;status.textContent=`Checking public place details · ${completed}/${candidates.length}`}}));persistTrip();renderItinerary();button.disabled=false;button.innerHTML='Auto-fill places <span>↗</span>';status.textContent=changed?`Added available photos or official websites to ${changed} place${changed===1?'':'s'}. Anything without a confident match was left unchanged.`:'No confident public matches were found, so nothing was changed.';toast(changed?`${changed} places completed`:'No place details changed')}
function itemLinks(item,city,index){let extra=item[5]||{},links=`<a href="${mapUrl(item,city)}" target="_blank" rel="noreferrer">Navigate ↗</a>`;if(extra.website)links+=`<a href="${extra.website}" target="_blank" rel="noreferrer">Website ↗</a>`;return `${links}<button class="auto-enrich-stop" data-auto-enrich="${index}" aria-label="Auto-fill photo and website for ${item[2]}">✦ Auto-fill</button><button class="edit-link-btn" data-edit-link="${index}" aria-label="Add or edit links for ${item[2]}">+ Link</button><button class="photo-upload-btn" data-photo-upload="${index}" aria-label="Upload photo for ${item[2]}">▧ ${extra.photo?'Replace':'Photo'}</button>${extra.photo?`<button class="remove-photo-btn" data-photo-remove="${index}" aria-label="Remove photo for ${item[2]}">Remove photo</button>`:''}`}
function renderItinerary(){let d=days[selected];document.querySelector('#day-kicker').textContent=`DAY ${String(selected+1).padStart(2,'0')} · ${d.dow}`;document.querySelector('#day-title').innerHTML=d.title;document.querySelector('#day-subtitle').textContent=`${d.date} ${selected>2?'November':'October'} 2026 · ${d.city}`;document.querySelector('#daily-notice').textContent=d.notice;document.querySelector('#modal-context').textContent=d.city.toUpperCase();document.querySelector('#day-meta').innerHTML=[['TODAY’S THEME',d.theme],['TONIGHT',d.hotel],['BUDGET',d.budget],['CHECK-IN','by 00:00']].map(x=>`<span>${x[0]}<b>${x[1]}</b></span>`).join('');document.querySelector('#date-rail').innerHTML=days.map((x,i)=>`<button class="date-tab ${i===selected?'active':''}" data-day="${i}"><small>${x.dow}</small><strong>${x.date}</strong><small>${x.city}</small></button>`).join('');document.querySelectorAll('.date-tab').forEach(b=>b.onclick=()=>{selected=+b.dataset.day;renderItinerary()});document.querySelector('#timeline').innerHTML=d.items.map((x,i)=>{let extra=x[5]||{},cn=chinesePlace(x[2]);return `${i?`<div class="travel-segment">${x[1]==='Transport'?'Travel segment':'12 min walk'} · ${x[4]}</div><button class="add-between" data-insert="${i}">+ Add stop here</button>`:''}<article class="timeline-item ${typeClass(x[1])}" draggable="true" data-index="${i}"><div class="item-time">${x[0]}<small>${x[4]}</small></div><div class="item-marker"></div><div class="item-card">${extra.photo?`<img class="place-photo" src="${extra.photo}" alt="${x[2]} visual reminder" onerror="this.remove()">`:''}<div class="item-top"><div><span class="item-type">${x[1].toUpperCase()}</span><h3 contenteditable="true" spellcheck="false">${x[2]}</h3>${cn?`<span class="chinese-place">${cn}</span>`:''}<p contenteditable="true" spellcheck="false">${x[3]}</p></div><div class="item-actions"><button class="item-menu" aria-label="Item actions" data-menu="${i}">···</button></div></div><div class="place-links">${itemLinks(x,d.city,i)}</div><div class="item-foot"><span class="status">${x[1]==='Meal'?'TO DECIDE':'CONFIRMED'}</span><span class="priority">${i<2?'Must do':'Flexible'}</span></div></div></article>`}).join('');let next=d.items.find(x=>x[1]!=='Transport'),nextExtra=next?.[5]||{},glance=document.querySelector('#place-glance');glance.className=`place-glance ${nextExtra.photo?'':'no-photo'}`;glance.innerHTML=`${nextExtra.photo?`<img src="${nextExtra.photo}" alt="">`:''}<div><span>NEXT PLACE · ${next?.[0]||''}</span><b>${mapQuery(next,d.city)}</b></div>`;document.querySelector('#today-route-link').href=mapUrl(next,d.city);bindTimeline()}
