// Saved places: a shared, location-organised collection linked to itinerary hearts.
function esc(value){return String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
let savedPlaces=[];try{savedPlaces=JSON.parse(localStorage.getItem('tabi-saved-places'))||[]}catch{}
function persistSavedPlaces(){localStorage.setItem('tabi-saved-places',JSON.stringify(savedPlaces))}
function savedKey(name,city){return `${normalName(name)}-${normalName(city)}`}
function cityCountry(city,fallBack=''){let map={Shanghai:'China',Beijing:'China',Guangzhou:'China',Chengdu:'China',XiAn:'China',Kyoto:'Japan',Osaka:'Japan',Miyazu:'Japan',Kinosaki:'Japan',Awaji:'Japan',Paris:'France',London:'United Kingdom',Rome:'Italy',Barcelona:'Spain',Sydney:'Australia',Melbourne:'Australia',Seoul:'South Korea',Taipei:'Taiwan',Singapore:'Singapore',Bangkok:'Thailand',Dubai:'United Arab Emirates',Istanbul:'Turkey',Cairo:'Egypt',Amsterdam:'Netherlands','New York':'United States','San Francisco':'United States','Los Angeles':'United States',Toronto:'Canada'};return map[city]||fallBack||'Unsorted'}
