renderHotels=function(){let list=document.querySelector('#hotel-list');if(!list)return;let visible=hotels.map((hotel,index)=>({hotel,index})).filter(({hotel})=>hotel&&!hiddenHotelBookings.has(hotelBookingKey(hotel)));list.innerHTML=visible.length?visible.map(({hotel,index})=>{let date=hotel[0]||'DATE TO CONFIRM',name=hotel[1]||'Hotel booking',details=hotel[2]||'Details to confirm',media=hotelMedia[name]||{},booking=media.website||hotel[3]||`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(name)}`,photo=media.photo?`url('${String(media.photo).replace(/'/g,'%27')}')`:'none',photoImage=media.photo?`<img class="hotel-card-photo" src="${media.photo}" alt="${name} photo">`:'';return `<article class="hotel-card" style="--hotel-photo:${photo}">${photoImage}<button class="hotel-photo-slot hotel-photo-upload" data-hotel-upload="${index}" aria-label="Upload or replace photo for ${name}">${media.photo?`<img src="${media.photo}" alt="${name}">`:''}<span class="hotel-photo-empty">⌂<small>${media.photo?'Replace photo':'Add photo'}</small></span><i>▧</i></button><div class="hotel-copy"><span class="eyebrow">${date}</span><b>${name}</b><small class="card-translation">${hotelChinese[name]||''}</small><small>${details}</small></div><div class="hotel-actions"><a href="${booking}" target="_blank" rel="noreferrer">Booking ↗</a><button data-hotel-fill="${index}">${media.photo?'Refresh photo':'Auto-fill photo'}</button>${media.photo?`<button class="hotel-remove-photo" data-hotel-remove-photo="${index}">Remove photo</button>`:''}<button class="booking-delete" data-delete-hotel="${index}">Delete</button></div></article>`}).join(''):'<p class="booking-empty">No hotel bookings yet.</p>';list.querySelectorAll('[data-hotel-fill]').forEach(button=>button.onclick=()=>autoEnrichHotel(+button.dataset.hotelFill));list.querySelectorAll('[data-hotel-upload]').forEach(button=>button.onclick=()=>{window.hotelUploadTarget=+button.dataset.hotelUpload;document.querySelector('#hotel-photo-upload').click()});list.querySelectorAll('[data-hotel-remove-photo]').forEach(button=>button.onclick=()=>{let hotel=hotels[+button.dataset.hotelRemovePhoto];if(!hotel)return;let name=hotel[1];if(!hotelMedia[name]?.photo)return;delete hotelMedia[name].photo;persistBookings();renderHotels();toast('Hotel photo removed')});list.querySelectorAll('[data-delete-hotel]').forEach(button=>button.onclick=()=>{let hotel=hotels[+button.dataset.deleteHotel];if(!hotel)return;hiddenHotelBookings.add(hotelBookingKey(hotel));persistBookings();renderHotels();toast('Hotel booking removed')});renderBookingManager()}
renderBookingManager=function(){let manager=document.querySelector('#booking-manager');if(!manager)return;manager.className='booking-manager';manager.innerHTML=`<section class="booking-section"><p class="eyebrow">HOTEL BOOKINGS</p><h2>Your hotel bookings</h2><details class="booking-add"><summary aria-label="Add hotel booking">＋ Add hotel booking detail</summary><form id="hotel-booking-form"><label>Hotel name<input name="name" required placeholder="e.g. The Tokyo Station Hotel"></label><label>Dates<input name="date" required placeholder="e.g. 12–15 Apr"></label><label>City / confirmation<input name="details" placeholder="Tokyo · Booking.com · Confirmed"></label><label>Booking link<input name="link" type="url" placeholder="https://..."></label><button>Add hotel booking</button></form></details></section><section class="booking-section"><p class="eyebrow">RESTAURANT BOOKINGS</p><h2>Restaurant bookings</h2><div id="restaurant-bookings">${(restaurantBookings||[]).filter(Boolean).map((booking,index)=>{let name=booking.name||'Restaurant booking',date=booking.date||'Date to confirm',details=booking.details||'Reservation';return `<article class="restaurant-booking"><div><b>${name}</b><small>${date} · ${details}</small></div><div>${booking.link?`<a href="${booking.link}" target="_blank" rel="noreferrer">Booking ↗</a>`:''}<button class="booking-delete" data-delete-restaurant="${index}">Delete</button></div></article>`}).join('')||'<p class="booking-empty">No restaurant bookings yet.</p>'}</div><details class="booking-add"><summary aria-label="Add restaurant booking">＋ Add restaurant booking detail</summary><form id="restaurant-booking-form"><label>Restaurant name<input name="name" required placeholder="e.g. Yakitori Omino"></label><label>Date & time<input name="date" required placeholder="e.g. 14 Apr · 19:30"></label><label>City / confirmation<input name="details" placeholder="Tokyo · 2 guests"></label><label>Booking link<input name="link" type="url" placeholder="https://..."></label><button>Add restaurant booking</button></form></details></section>`;manager.querySelector('#hotel-booking-form').onsubmit=event=>{event.preventDefault();let form=new FormData(event.currentTarget);hotels.push([form.get('date'),form.get('name'),form.get('details')||'Pending confirmation',form.get('link')]);persistBookings();renderHotels();toast('Hotel booking added')};manager.querySelector('#restaurant-booking-form').onsubmit=event=>{event.preventDefault();let form=new FormData(event.currentTarget);restaurantBookings.unshift({name:form.get('name'),date:form.get('date'),details:form.get('details'),link:form.get('link')});persistBookings();renderBookingManager();toast('Restaurant booking added')};manager.querySelectorAll('[data-delete-restaurant]').forEach(button=>button.onclick=()=>{restaurantBookings.splice(+button.dataset.deleteRestaurant,1);persistBookings();renderBookingManager();toast('Restaurant booking removed')})};renderHotels();
const renderBookingManagerWithStayTimes=renderBookingManager;renderBookingManager=function(){renderBookingManagerWithStayTimes();let form=document.querySelector('#hotel-booking-form');if(!form)return;let oldDateField=form.querySelector('input[name="date"]')?.closest('label');if(oldDateField)oldDateField.outerHTML='<div class="stay-dates"><label>Check-in date<input name="checkinDate" type="date" required></label><label>Time<input name="checkinTime" type="time" value="15:00"></label><label>Check-out date<input name="checkoutDate" type="date" required></label><label>Time<input name="checkoutTime" type="time" value="11:00"></label></div>';form.onsubmit=event=>{event.preventDefault();let data=new FormData(form),checkin=`${data.get("checkinDate")} ${data.get("checkinTime")||''}`.trim(),checkout=`${data.get("checkoutDate")} ${data.get("checkoutTime")||''}`.trim();hotels.push([`${checkin} → ${checkout}`,data.get('name'),data.get('details')||'Pending confirmation',data.get('link')]);persistBookings();renderHotels();toast('Hotel booking added')};};renderHotels();

/* Journal: visited stops, six-memory photo strips and a connected route map. */
let journalMapInstance=null;
function journalVisitedStops(){const result=[];days.forEach((day,dayIndex)=>(day.items||[]).forEach((item,itemIndex)=>{const extra=item[5]||{};if(extra.visited)result.push({day,dayIndex,item,itemIndex,extra})}));return result}
