  kansaiinternationalairport:[34.4347,135.244],arriveatkansaiinternationalairport:[34.4347,135.244],
  dotonboridinner:[34.6687,135.5013],dotonbori:[34.6687,135.5013],
  kyotoimperialpalace:[35.0254,135.7621],kamogawadelta:[35.0237,135.773],
  kiyomizudera:[34.9949,135.785],sannenzakaninenzaka:[34.9976,135.7801],
  kodaijinenenomichi:[35.0007,135.7808],gionshirakawa:[35.005,135.775],
  arashiyamabamboogrove:[35.017,135.671],jojakkojigioji:[35.0215,135.666],togetsukyobridge:[35.0094,135.6677],
